fn encode(ffmpeg: &str, c: &Case) -> std::path::PathBuf {
    let out = common::tmp(&format!("{}.h264", c.name));
    common::run(
        Command::new(ffmpeg)
            .args(["-v", "error", "-y", "-f", "lavfi", "-i", c.source])
            .args(["-frames:v", "1", "-c:v", "libx264", "-pix_fmt", c.pix_fmt])
            .args(["-profile:v", c.profile])
            .args(c.args)
            .arg(&out),
    );
    out
}

#[test]
fn bit_exact_against_ffmpeg() {
    let Some(ffmpeg) = common::ffmpeg() else {
        eprintln!("ffmpeg not found; skipping the synthetic oracle tests");
        return;
    };
    let mut failures = Vec::new();
    for c in CASES {
        let path = encode(&ffmpeg, c);
        let data = std::fs::read(&path).expect("read stream");
        let cfg = DecoderConfig::annex_b();
        assert_eq!(access_unit_kind(&data, &cfg), FrameKind::Idr, "{}", c.name);
        let want = common::reference(
            &ffmpeg,
            &path,
            c.pix_fmt,
            &common::tmp(&format!("{}.yuv", c.name)),
        );
        match decode_access_unit(&data, &cfg) {
            Ok(pic) => {
                let (bad, first) = common::compare(&pic, &want);
                if bad != [0; 3] {
                    failures.push(format!("{}: mismatches {bad:?}, first {first:?}", c.name));
                } else {
                    eprintln!("{}: bit-exact", c.name);
                }
            }
            Err(e) => failures.push(format!("{}: {e}", c.name)),
        }
    }
    assert!(failures.is_empty(), "\n{}", failures.join("\n"));
}
